        // 画像の切り替え
        event_perform(ev_keypress, vk_up);
    }else{
        // Ctrl押されてる場合はズーム
        global.img_scale = min(global.img_scale+0.2, IMAGE_SCALE_MAX);
        //draw_background_ext(background_index[0], 0, 0, img_scale, img_scale, 0, c_white, 1);
        
        // 背景画像を拡大するパターン（ガスが大きくならないがボタンを修正しなくていい)
        /*
        background_xscale[0] = img_scale;
        background_yscale[0] = img_scale;
        background_x[0] = - global.hip_hole_x[global.cur_bkg_index]*img_scale + global.hip_hole_x[global.cur_bkg_index];
        background_y[0] = - global.hip_hole_y[global.cur_bkg_index]*img_scale + global.hip_hole_y[global.cur_bkg_index];
*/
        // ビューを変えるパターン（ガスも大きくなるが、ボタンが見えなくなる可能性大)
        fit_window_size_to_image(background_index[0], global.img_scale);
    }
}
